function EXTRA(R,ICON){
 /* hook: the plant loop, and where its heat goes (35.3 % work, 64.7 % to the condenser in the first worked example) */
 ICON.rkLoop=(x,y)=>`<g transform="translate(${x-190} ${y-80})">${RK_box(0,0,380,160,{fill:'#FFFFFF',st:RK_GREY,sw:3,r:18})}
  ${RK_box(20,40,90,80,{fill:'#FFD8A8',st:ORG,sw:3,r:10})}${RK_T(65,88,'boiler',{fs:20,fw:800,a:'middle',fill:ORG})}
  <path d="M170,60 L240,40 L240,120 L170,100 Z" fill="#E7F5FF" stroke="${BLU}" stroke-width="3"/>${RK_T(205,150,'turbine',{fs:20,fw:800,a:'middle',fill:BLU})}
  ${RK_box(280,50,84,60,{fill:'#EBFBEE',st:GRN,sw:3,r:10})}${RK_T(322,86,'cool',{fs:20,fw:800,a:'middle',fill:GRN})}
  ${RK_arrow(110,64,168,72,RK_DARK,3)}${RK_arrow(240,80,278,80,RK_DARK,3)}
  ${RK_pl([[322,110],[322,140],[65,140]],RK_DARK,3)}${RK_arrow(65,140,65,124,RK_DARK,3)}
  <path d="M40,32 q8,-12 0,-24 M60,32 q8,-12 0,-24 M80,32 q8,-12 0,-24" fill="none" stroke="${SLT}" stroke-width="3"/></g>`;
 ICON.rkThird=(x,y)=>`<g transform="translate(${x-190} ${y-80})">${RK_box(0,0,380,160,{fill:'#FFFFFF',st:ORG,sw:3,r:18})}
  ${RK_T(20,38,'heat in: 3018.7 kJ/kg',{fs:22,fw:800,fill:RK_DARK})}
  <rect x="20" y="58" width="${(340*0.353).toFixed(1)}" height="46" fill="${BLU}"/><rect x="${(20+340*0.353).toFixed(1)}" y="58" width="${(340*0.647).toFixed(1)}" height="46" fill="${SLT}" fill-opacity=".55"/>
  ${RK_T(20+340*0.353/2,89,'35.3 %',{fs:22,fw:800,a:'middle',fill:'#FFFFFF'})}${RK_T(20+340*0.353+340*0.647/2,89,'64.7 %',{fs:22,fw:800,a:'middle',fill:RK_DARK})}
  ${RK_T(20,138,'work',{fs:22,fw:800,fill:BLU})}${RK_T(360,138,'to the condenser',{fs:22,fw:700,a:'end',fill:RK_GREY})}</g>`;
 /* recap pictures: each fills most of its card (about 420 × 330) */
 ICON.rkCycle=(x,y)=>{const m=RK_map(x-200,y-150,400,270,8.8,450);return RK_dome(m)+RK_L(m.X(0),m.Y(0),m.X(8.8),m.Y(0),RK_DARK,3)+RK_L(m.X(0),m.Y(0),m.X(0),m.Y(450),RK_DARK,3)+RK_cycle(m,{w:5,r:7})
  +RK_T(m.X(6.771)+12,m.Y(400)+8,'1',{fs:24,fw:800,fill:BLU})+RK_T(m.X(6.771)+12,m.Y(45.8)-8,'2',{fs:24,fw:800,fill:BLU})+RK_T(m.X(0.649)+6,m.Y(45.8)-14,'3, 4',{fs:22,fw:800,fill:GRN})
  +RK_T(m.X(4.2),m.Y(150),'η = 35.3 %',{fs:26,fw:800,a:'middle',fill:BLU})};
 ICON.rkReheat=(x,y)=>{const m=RK_map(x-200,y-150,400,270,8.8,550);return RK_dome(m)+RK_L(m.X(0),m.Y(0),m.X(8.8),m.Y(0),RK_DARK,3)+RK_L(m.X(0),m.Y(0),m.X(0),m.Y(550),RK_DARK,3)
  +RK_L(m.X(6.883),m.Y(500),m.X(6.883),m.Y(240),BLU,5)+RK_ts(m,[[6.883,240],[7.155,308.2],[7.377,372.2],[7.578,436.1],[7.764,500]],RED,5)+RK_L(m.X(7.764),m.Y(500),m.X(7.764),m.Y(45.8),BLU,5)
  +RK_L(m.X(6.883),m.Y(240),m.X(6.883),m.Y(45.8),SLT,3,'stroke-dasharray="7 6"')+RK_L(m.X(7.764),m.Y(45.8),m.X(0.649),m.Y(45.8),GRN,4)
  +RK_T(m.X(6.883)-10,m.Y(45.8)-12,'0.831',{fs:22,fw:800,a:'end',fill:SLT})+RK_T(m.X(7.764)+10,m.Y(45.8)-12,'0.949',{fs:24,fw:800,fill:BLU})
  +RK_T(m.X(7.8)+8,m.Y(330),'reheat',{fs:22,fw:800,fill:RED})};
 ICON.rkRegen=(x,y)=>`<g transform="translate(${x-205} ${y-155})">
  ${RK_box(100,96,170,124,{fill:'#FFF4E6',st:ORG,sw:3,r:12})}${RK_T(185,150,'open',{fs:26,fw:800,a:'middle',fill:ORG})}${RK_T(185,182,'heater',{fs:26,fw:800,a:'middle',fill:ORG})}
  ${RK_arrow(185,6,185,92,ORG,5)}${RK_T(200,44,'bled m = 0.173',{fs:22,fw:800,fill:ORG})}
  ${RK_arrow(0,170,96,170,BLU,4)}${RK_T(0,154,'1 − m',{fs:22,fw:800,fill:BLU})}
  ${RK_box(318,86,92,144,{fill:'#FFD8A8',st:ORG,sw:3,r:12})}${RK_T(364,166,'boiler',{fs:22,fw:800,a:'middle',fill:ORG})}
  ${RK_arrow(270,158,314,158,RED,5)}${RK_T(292,262,'hot feedwater',{fs:22,fw:800,a:'middle',fill:RED})}
  ${RK_T(150,300,'η: 38.4 → 40.8 %',{fs:28,fw:800,a:'middle',fill:GRN})}</g>`;
}
